import re
from pathlib import Path
p=Path('docs/planning/tasks.md')
s=p.read_text()
heads=re.findall(r'^### (T\d{3})\b',s,re.M)
deps=[]
for line in s.splitlines():
    if 'Dependencies:' in line:
        deps.append((line.split('Dependencies:',1)[0],re.findall(r'\bT\d{3}\b',line.split('Dependencies:',1)[1]),line))
print('headings',len(heads),len(set(heads)))
print('dependency_fields',len(deps))
print('missing_heading_ids',sorted({x for _,ds,_ in deps for x in ds}-set(heads)))
print('duplicate_headings',sorted({x for x in heads if heads.count(x)>1}))
graph={h:[] for h in heads}
current=None
for line in s.splitlines():
    m=re.match(r'^### (T\d{3})\b',line)
    if m: current=m.group(1)
    if current and 'Dependencies:' in line:
        graph[current].extend(re.findall(r'\bT\d{3}\b',line.split('Dependencies:',1)[1]))
vis={}; stack=[]; cycles=[]
def dfs(n):
    vis[n]=1;stack.append(n)
    for d in graph[n]:
        if d not in graph: continue
        if vis.get(d)==1: cycles.append(stack[stack.index(d):]+[d])
        elif not vis.get(d): dfs(d)
    stack.pop();vis[n]=2
for n in graph:
    if not vis.get(n): dfs(n)
print('cycles',cycles)
for n in heads:
    print(n,','.join(graph[n]) or '-')
PY
